blocks_correct=[(1,1,9,[[1,0,1],[1,1,1],[0,1,0]]),
        (1,7,6,[[0,1,1],[0,1,1],[1,0,0]]),
        (7,1,3,[[1,0,1],[0,1,1],[0,1,0]]),
        (7,7,4,[[1,1,1],[0,1,0],[0,1,0]])]
out2=[[2]*13 for _ in range(13)]
for r,c,color,mask in blocks_correct:
    for i in range(5):
        for j in range(5): out2[r+i][c+j]=color
